// Generated by /ship test coverage audit (pass 2).
// Value: protects=Confirm with missing city or blank address shows the validation message, keeps the picker open and saves nothing;
//   fails_when=the saveLocation guard is removed or weakened (e.g. whitespace-only address accepted);
//   why_new=e2e covers only a valid save; seam=none
// Value: protects=Use my current location shows the unavailable, denied and detected messages;
//   fails_when=the geolocation guard or a success/error callback is dropped or swapped;
//   why_new=no test exercises geolocation; seam=none
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { SimProvider } from '../lib/sim';
import { LOCATION_KEY } from '../lib/discovery';
import Landing, { CHOOSE_LOCATION_EVENT } from './Landing';

const ERROR = 'Choose your city and enter a delivery address to continue.';

function openPicker() {
  render(<SimProvider><Landing go={vi.fn()} /></SimProvider>);
  act(() => { window.dispatchEvent(new Event(CHOOSE_LOCATION_EVENT)); });
  expect(screen.getByRole('heading', { name: 'Where should we deliver?' })).toBeTruthy();
}

const confirm = () => fireEvent.click(screen.getByRole('button', { name: /Confirm location/ }));
const status = () => screen.queryByRole('status')?.textContent ?? '';

describe('Landing location picker', () => {
  const originalGeo = Object.getOwnPropertyDescriptor(navigator, 'geolocation');

  beforeEach(() => {
    localStorage.clear();
    // framer-motion's whileInView needs IntersectionObserver, which jsdom lacks.
    vi.stubGlobal('IntersectionObserver', class { observe() {} unobserve() {} disconnect() {} takeRecords() { return []; } });
  });
  afterEach(() => {
    cleanup();
    vi.unstubAllGlobals();
    if (originalGeo) Object.defineProperty(navigator, 'geolocation', originalGeo);
    else delete (navigator as { geolocation?: unknown }).geolocation;
  });

  it.each([
    ['no city, no address', '', ''],
    ['city but blank address', 'Lagos', '   '],
    ['address but no city', '', '12 Herbert Macaulay Way'],
  ])('rejects %s and saves nothing', (_name, city, address) => {
    openPicker();
    if (city) fireEvent.change(screen.getByLabelText('City'), { target: { value: city } });
    fireEvent.change(screen.getByLabelText('Delivery address'), { target: { value: address } });
    confirm();
    expect(status()).toBe(ERROR);
    expect(screen.getByRole('heading', { name: 'Where should we deliver?' })).toBeTruthy();
    expect(localStorage.getItem(LOCATION_KEY)).toBeNull();
  });

  it('saves a valid location and closes the picker', () => {
    openPicker();
    fireEvent.change(screen.getByLabelText('City'), { target: { value: 'Lagos' } });
    fireEvent.change(screen.getByLabelText('Delivery address'), { target: { value: '  12 Herbert Macaulay Way ' } });
    confirm();
    expect(screen.queryByRole('heading', { name: 'Where should we deliver?' })).toBeNull();
    expect(JSON.parse(localStorage.getItem(LOCATION_KEY)!)).toEqual({ country: 'Nigeria', city: 'Lagos', address: '12 Herbert Macaulay Way' });
  });

  const useMyLocation = () => fireEvent.click(screen.getByRole('button', { name: /Use my current location/ }));
  const setGeo = (value: unknown) => Object.defineProperty(navigator, 'geolocation', { value, configurable: true });

  it('explains when geolocation is unavailable', () => {
    setGeo(undefined);
    openPicker();
    useMyLocation();
    expect(status()).toMatch(/unavailable in this browser/);
  });

  it('explains when geolocation is denied', () => {
    setGeo({ getCurrentPosition: (_ok: () => void, fail: () => void) => fail() });
    openPicker();
    useMyLocation();
    expect(status()).toMatch(/couldn’t access your location/);
  });

  it('asks for a street address after geolocation succeeds', () => {
    setGeo({ getCurrentPosition: (ok: () => void) => ok() });
    openPicker();
    useMyLocation();
    expect(status()).toMatch(/^Location detected/);
    expect(localStorage.getItem(LOCATION_KEY)).toBeNull(); // detection alone never saves
  });
});
